package com.zest.products.auth;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long minutes; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.access-token-minutes}") long minutes){if(secret.getBytes(StandardCharsets.UTF_8).length<32)throw new IllegalArgumentException("JWT secret must be >= 32 bytes");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.minutes=minutes;} public String create(AppUser u){return Jwts.builder().subject(u.getUsername()).claim("roles",u.getRoles()).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(minutes,ChronoUnit.MINUTES))).signWith(key).compact();} public Jws<Claims> parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token);} }
